def is_safe_substitution(expression):
    def explore(sub_expr):
        if not sub_expr:
            return []
        tokens = sub_expr.split()
        if '+' in tokens or '-' in tokens or '*' in tokens or '/' in tokens:
            for i, token in enumerate(tokens):
                if token in ['+', '-', '*', '/']:
                    new_tokens = tokens[:i] + ['('+token+'*',explore(tokens[i+2:]) + ')'] + tokens[i+2:]
                    new_sub_expr = ' '.join(new_tokens)
                    return max(explore(new_sub_expr), explore(new_sub_expr), key=len)
        elif '(' in tokens:
            new_sub_expr = explore('('+explore(sub_expr)+')')
            return explore(new_sub_expr)
        else:
            return explore(''.join(tokens))
    return explore(expression)

def is_suspicious(expression):
    for i, item in enumerate(expression.split()):
        if item and item[0].isalpha():
            return 'Suspicious'
    return 'OK' if is_safe_substitution(expression) == max(is_safe_substitution(expression)) else 'Suspicious'

