from collections import deque

def temperature_component_score(a, b, x):
    """Calculate the path and score components based on temperature."""
    m, n = len(a), len(b)
    score = 0
    for i in range(n):
        if i + 1 >= x:
            for j in range(x, i + 1):
                score -= a[j-1] + b[i]
        if i + 1 >= x:
            for j in range(i + 1):
                score += a[j] + b[i]
    return score

def bfs(grid):
    """Perform BFS starting from [-1, -1]."""
    queue = deque([(0, 0)])
    visited = [[-1]*m for _ in range(n)]
    visited[0][0] = 0
    while queue:
        r, c = queue.popleft()
        for dr, dc in [[1, 0], [0, 1], [-1, 0], [0, -1]]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] > grid[r][c]:
                visited[nr][nc] = 1
                queue.append((nr, nc))
    return visited

def solve(n, m, q, a, b, x):
    grid = [[0]*m for _ in range(n)]
    for i in range(m):
        for j in range(n):
            grid[j][i] = a[j] + b[i]
    result = []
    for _x in range(q):
        score = temperature_component_score(a, b, x)
        hasBorder = False
        # Check if there's at least one border cell
        for i in range(n):
            if max([min(g[i+j] for g in grid)] for j in range(m)) >= x:
                hasBorder = True
                break
        # If all cells are below x
        if not hasBorder:
            if x > max([min(grid[i][j] for j in range(m)) for i in range(n)]):
                score += 2
            else:
                score -= 4
        result.append(score)
    return result

