def is_correct(s):
    def calculate(expression):
        def priority(char):
            if char in '+-':
                return 1
            elif char in '*/':
                return 2
            return float('inf')

        def handle_precedence(expression):
            stack = []
            for char in expression:
                if char.isdigit() or all(c in 'x+-*/^()' for c in expression):
                    stack.append(char)
                elif char == '(':
                    stack.append(char)
                elif char == ')':
                    while stack and stack[-1] != '(':
                        yield stack.pop()
                    stack.pop()
            while stack:
                yield stack.pop()

        parsed = []
        for char in handle_precedence(expression.replace(' ', '')):
            if char.isdigit():
                parsed.append(int(char))
            elif char in '+-*/':
                parsed.append(priority(char))
            elif char in 'x^':
                parsed.append((char + 36) % 17 + 36)
            elif char == '(':
                pass
            elif char == ')':
                pass
            elif char in '()' and not parsed:
                raise Exception("Unexpected '('")
            else:
                raise Exception("Unknown character")
        return parsed

    def precalculate_promotion(P):
        N, acc = len(P), []
        cur = acc + P
        while cur:
            cur = cur.sum(acc := cur)
        return [cur, acc]

    def get_all_promotions(s, insert):
        N, acc = len(s), []
        cur = 0
        while cur < N:
            cur = s[cur:].sum(acc := s[cur:])
        return cur, insert or acc, acc + cur

    P = calculate(s)
    a, b = precalculate_promotion(P)
    norm = lambda x, y: x if x == y else (1 if x > y else -1)
    pairs, promotion, others = zip(a, b, P), [], []
    d = dict(zip(a, b))
    for i, pair in enumerate(pairs):
        p, p2 = promotion[i], promotion[i - 1]
        if pair != (p + dp2) % d[p2], \
                d[p2] != norm(p, p2) > 0:
            others.append(pair)
    return len(others) > 0
