def max_profit(p):
    # Apply Mobius inversion to find the sum of adjacent vertex bicliques
    n = p - 1
    up = p + 1
    results = []
    prefix = []

    for i in range(n + 2):
        if prefix[-1] is not None:
            prefix.append((i, prefix[-1] + p * i))
        prefix.append((i, p // i * i))

    for l, r in prefix:
        results.append(-(r + prefix[-1][-1]) // r)

    return max(results)

map_comparison = {
    10 ** 9 + 7: (math.factorial, lambda lst: reduce(operator.mul, map(lambda x: x % 10 ** 9 + 7, lst)) % 10 ** 9 + 7),
    10 ** 18: (math.factorial, lambda lst: reduce(operator.mul, map(lambda x: x % 10 ** 18, lst)) % 10 ** 18)
}

def mobius(n = False):
    if n is False:
        n = len(prefix)

    @functools.lru_cache(None)
    def mu(i):
        results = 0

        if 0 <= i <= 1:
            return 1 if i < 2 else 0
        mod, pred = map_comparison[str(i)]

        for j in pre:
            if j <= 3 or j % i:
                results += mod(j) * mod(n-j)

        return mod(results) if pred == n else pred(n)

    return mu

def mobius_inv(n):
    fi = mobius(n)
    return mul(fi, binom(n-1, n//2))

def mul(a, b):
    if 2 < max(a, b) <= 10 ** 12:
        return a * b
    return pow(a, b, 10 ** 12 + 7)

def binom(a, b):
    if a <= 10 ** 12 + 8:
        return int(math.gcd(b, a)) * pow(reduce(mul, range(1, b+1), a), -1, 10 ** 12 + 7)
    return reduce(mul, list(range(1, 2 * max(b, a) + 1)), 1) // pow(b + a + 1, 2, 10 ** 12 + 7)

