import sys

class TreeReconstructor:
    def __init__(self):
        self.tree = [None] * 1001
        self.leaves = []

    def ask_question(self, a1, a2, a3):
        sys.stdout.write(f"{a1} {a2} {a3}\n")
        sys.stdout.flush()
        return sys.stdin.readline().strip()

    def solve(self):
        self.leaves = [
            i for i in range(1, len(self.tree) + 1) if self.tree[i] == None
        ]

        while len(self.leaves) > 2:
            a1 = self.leaves.pop(0)
            a2 = self.leaves.pop(0)
            a3 = self.leaves.pop(0)

            depth = self.ask_question(a1, a2, a3).upper()

            if depth == "X":
                self.tree[a2] = self.leaves.pop(0)

            elif depth == "Y":
                self.tree[a3] = self.leaves.pop(0)

            else:
                self.tree[a1] = self.leaves.pop(0)

        a1 = self.leaves.pop(0)
        a2 = self.leaves.pop(0)
        depth = self.ask_question(a1, a2, None)

        if depth == "X":
            self.tree[a2] = a1

        elif depth == "Y":
            self.tree[a1] = a2

        else:
            self.tree[a2] = self.leaves.pop(0)

        while len(self.leaves) > 1:
            a3 = self.leaves.pop(0)
            a4 = self.leaves.pop(0)
            a5 = self.leaves.pop(0)

            depth = self.ask_question(a3, a4, a5).upper()

            if depth == "X":
                self.tree[a4] = a3
                self.tree[a5] = a3

            elif depth == "Y":
                self.tree[a3] = a4
                self.tree[a4] = a5

            else:
                self.tree[a3] = a5

        root = self.leaves[0]
        for i in range(2, len(self.tree) + 1):
            self.tree[i] = root

        print("-1")
        for node in range(1, len(self.tree) + 1):
            print(node, '\n', end='', flush=True)

        sys.stdout.flush()

