# Function to check if two circles are intersecting or touching
def circles_intersect(c1, c2):
    x1, y1, r1 = c1
    x2, y2, r2 = c2
    d = math.sqrt((x2 - x1)**2 + (y2 - y1)**2)
    return d <= r1 + r2 or d == 0

# Function to calculate the minimal area square enclosing a circle
def minimal_square_enclosing_circle(c):
    x, y, r = c
    dx = r + math.sqrt(r*r - (y - r)**2)
    dy = r + math.sqrt(r*r - (x - r)**2)
    return max(dx, dy)**2

# Function to calculate the minimal circle passing through two points without intersecting circles
def minimal_circle_through_two_points(c1, c2, circles):
    # Check if any two circles intersect or touch
    for i in range(len(circles)):
        for j in range(i + 1, len(circles)):
            if circles_intersect(circles[i], circles[j]):
                return -1  # Indicates an invalid configuration
    x0, y0, r0 = c1
    xmin, ymin, xmax, ymax = x0 - r0, y0 - r0, x0 + r0, y0 + r0

    # If circles do not intersect, return the minimal square enclosing the circle
    if not any(circles_intersect(c, (x0, y0, r0)) for c in circles):
        return minimal_square_enclosing_circle((x0, y0, r0))

    # Take the intersection point of the lines connecting the circles
    for i in range(len(circles)):
        for j in range(i + 1, len(circles)):
            m = (circles[i][1] - circles[j][1]) / (circles[i][0] - circles[j][0])
            b = circles[i][1] - m * circles[i][0]
            d = math.sqrt(math.pow((x0 - circles[0][0]), 2) + math.pow((y0 - circles[0][1]), 2))
            if d > r0:
                t = (d * (m * (x0 - circles[0][0]) + b) - math.sqrt(math.pow(d, 2) - math.pow(d * (m * (x0 - circles[0][0]) + b), 2))) / r0
                u = d * t - (m * (x0 - circles[0][0]) + b)
                x = circles[i][0] + t * (circles[i][0] - circles[j][0])
                y = circles[i][1] + t * (circles[i][1] - circles[j][1])
                if 0 <= m <= 1:
                    if (x0 - x) ** 2 + (y0 - y) ** 2 <= (d + r0) ** 2:
                        return minimal_square_enclosing_circle((x0, y0, r0 - ((d + r0) - x0 - x) / t))
                    elif (x2 * y3 - x3 * y2).real < 0:
                        y = y0 + m * ((x0 - x2) - m * (y0 - y2))
                        if (x0 - x) ** 2 + (y0 - y) ** 2 <= r0 ** 2:
                            return minimal_square_enclosing_circle((x0, y0, r0 - ((y - y0) - m * (y - y0) - r0) / m))

    # If no intersections are found, return the minimal square enclosing the circle
    return minimal_square_enclosing_circle((x0, y0, r0))

