from collections import deque
from sympy import mod_inverse

def eval_expression(s):
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack and stack[-1] == '(':
                stack.pop()
                continue
            stack.append(c)

    stack.reverse()
    return ''.join(stack)

def build_expression(s):
    q = deque()
    depth = 0
    expression = ''
    for i in range(len(s)):
        if s[i] == '(':
            q.append(s[i])
            depth += 1
        elif s[i] == ')' and not q:
            return None
        elif s[i] == ')':
            if q and q[-1] == '(':
                q.pop()
                depth -= 1
            else:
                expression += ')' * (depth * 2 + 1)
                q.append(s[i])
                depth += 2

    while q:
        expression += ')' * q.popleft()
        depth -= 1

    return expression

def find_depth(s):
    expression = build_expression(s)
    while expression and expression[0] == '(':
        expression = expression[1:]
    while expression and expression[-1] == ')':
        expression = expression[:-1]

    q = deque()
    depth = {}
    for c in expression:
        if c == '(':
            q.append(c)
            depth[c] = 0
        elif c == ')':
            if q and q[-1] == '(':
                depth[q.pop()] = 1
            depth[q.pop()] += 1

    total_depth = 0
    for k, v in depth.items():
        total_depth += v

    ans = 1
    mod = 998244353
    for v in depth.values():
        if v == 0:
            ans = (ans * v) % mod
        elif v == 1:
            temp = mod - v
            temp %= mod
            ans = (ans * temp) % mod
    return total_depth * ans % mod

