def min_operations_to_convert(s, t):
    n, m = len(s), len(t)
    if n != m:
        return -1
    s = list(s)
    t = list(t)
    diff = []
    # Calculate number of differing bits
    for i in range(n):
        diff.append(s[i] != t[i])
    # Binary search to find the minimum number of operations
    left, right = 0, len(diff) - 1
    while left <= right:
        mid = (left + right) // 2
        if sum(diff[:mid+1]) < sum(diff[mid+1:]):
            right = mid - 1
        else:
            left = mid + 1
    return left if sum(diff[:left+1]) == sum(diff) else -1

