import math
from collections import defaultdict
from heapq import heappop, heappush

def dijkstra(graph, start):
    dist = {v: float('inf') for v in graph}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        (cost, u) = heappop(pq)
        if cost > dist[u]:
            continue
        for v, weight in graph[u]:
            if cost + weight < dist[v]:
                dist[v] = cost + weight
                heappush(pq, (dist[v], v))
    return dist

def find_max_profit(tree, weights, values, start, end):
    graph = defaultdict(list)
    for (u, v, w) in zip(tree[:-1], tree[1:], weights):
        graph[u].append((v, w))
        graph[v].append((u, w))
    result = 0
    for query in queries:
