        def helper(current, path):
            nonlocal prof
            path = tuple(sorted(path))
            if path in visited:
                return
            visited.add(path)
            if len(path) == 2 and path[0] == start and path[1] == end:
                profit = sum(values[path[i]] - weights[path[i]][path[(i + 1) % 2]] for i in range(len(path) - 1))
                prof = max(prof, profit)
            elif len(path) == 2 and path[0] == end and path[1] == start:
                prof = max(prof, weights[path[0]][path[1]] + sum(values[path[i]] for i in range(len(path) - 1)))
            else:
                for neighbor, weight in graph[path[0]].items():
                    if neighbor != path[(path.index(path[-1]) + 1) % 2]:
                        helper(neighbor, tuple(sorted(path[1 :] + (neighbor,), key=lambda x: (x[0] > x[1], x))))
        visited = set()
        helper(start, (start,))
        return prof

