    m = len(grid)
    q = deque()
    for i in range(m):
        for j in range(n):
            if grid[i][j] - x < 0:
                q.append((grid[i][j] - x, i, j))
    for i in range(m - 1, -1, -1):
        for j in range(n):
            if q and q[0][1] == i and q[0][2] == j:
                grid[i][j] = q.popleft()
                break
    match = [0] * n
    for i in range(m):
        basemin = min(accumulate(grid[i]), defaultdict(list)[min(accumulate(grid[i]))].popgrid)
        match[i] = find(grid[i], x) - basemin
    return match

def find(grid, x):
    m = len(grid)
    q = deque()
    for k in range(101):
        for i in range(m):
            for j in range(len(grid[-(i + 1)])):
                if grid[-(i + 1)][j] + k >= x:
                    q.appendleft((grid[-(i + 1)][j] + k, len(grid) - i - 1, j))
    return q.popleft()[1]

