def findBadTuples(num):
    primes = []
    for i in range(2, num+1):
        if all(i % j != 0 for j in range(2, int(i**0.5)+1)):
            primes.append(i)
    prime_factors = []
    for prime in primes:
        for n in range(prime, num+1, prime):
