        return 0
    factor_count, factors = findBadTuples(num)
    factor_counter = Counter(factors).values()
    subset_count = 1  # Include the empty subset
    for i in range(1, num+1):
        if all((factor is None) or (i % factor[0] == 0) and (factor[1] % i == 0) for factor in factors):
