def flip_binary_string(S, T):
    operations = 0
    S_position, T_position = 0, 0
    while S_position < len(S) or T_position < len(T):
        while S_position < len(S) and S[S_position] == '1':
            operations += 1
            S = '1' + S[1:]
        if operations % 2 == 1 and T_position < len(T) and T[T_position] == '0':
            S = S[:-1] + '0' + S[1:]
            operations -= 1
        while T_position < len(T) and T[T_position] == '1':
            operations += 1
            T = T[1:] + '1'
        if operations % 2 == 1 and S_position < len(S) and S[S_position] == '0':
            T = T[:-1] + '0' + T[1:]
            operations -= 1
        S_position, T_position = 0, 0
    return 2 * abs(len(S) - len(T) + (S == T))

