from collections import defaultdict

def min_tiredness(heights, tirednesses, edges):
    n = len(heights)
    graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    dp = [[float('inf')] * (1 << 19) for _ in range(n)]
    dp[0][0] = 0

    for partition in range(1 << (n - 1)):
        for j in range(n - 1):
            if (partition >> j) & 1 == 0:
                continue
            for neighbor in graph[j + 1]:
                if partition & (1 << (j + 1)):
                    dp[partition][j + 1] = min(dp[partition][j + 1], dp[partition ^ (1 << j)][j] + tirednesses[j + 1])
                    partition &= ~(1 << (j + 1))

    min_yet = float('inf')
    for bits in range(1, 1 << (n - 1)):
        if bits == 0:
            continue
        path_tiredness = tirednesses[0]
        for j in range(n - 1):
            if not (bits >> j & 1):
                continue
            if j == 0:
                path_tiredness = 0
            else:
                path_tiredness += tirednesses[j - 1]
            if bits & (1 << j):
                path_tiredness += dp[bits ^ (1 << j)][j]
        min_yet = min(min_yet, path_tiredness)

    return min_yet

