from collections import defaultdict
from heapq import heappop, heappush
from math import inf

def read_input(file):
    with open(file, 'r') as f:
        n = int(f.readline().strip())
        heights = list(map(int, f.readline().strip().split()))[:-1]
        tiredness = list(map(int, f.readline().strip().split()))[1:]
        graph = [[] for _ in range(n + 1)]
        for _ in range(n - 1):
            u, v = map(int, f.readline().strip().split())
            graph[u].append(v)
            graph[v].append(u)
        return n, heights, tiredness, graph

def dijkstra(graph, start):
    distances = {node: inf for node in range(1, len(graph) + 1)}
    priority_queue = [(0, start)]
    distances[start] = 0
    
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)
        
        if current_distance > distances[current_node]:
            continue
        
        for neighbor in graph[current_node]:
            distance = current_distance + (tiredness[neighbor - 1] - height[current_node - 1] if graph[current_node].index(neighbor) % 2 == 0 else tiredness[current_node - 1] - height[neighbor - 1])
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(priority_queue, (distance, neighbor))
                    
    return distances

def solve(graph, heights, tiredness, start):
    total_tiredness = 0
    shortest_distance = {node: inf for node in range(1, len(graph) + 1)}
    for i in range(1, len(graph) + 1):
        if tiredness[i - 1] < heights[i - 1]:
            shortest_distance[i] = int(1e9)
        elif i == 1:
            shortest_distance[i] = tiredness[i] + heights[i - 1]
        else:
            shortest_distance[i] = tiredness[i] + heights[i - 1] + dijkstra(graph, shortest_distance[i // 2])[i]
    
    for i in range(1, len(graph) + 1):
        total_tiredness += shortest_distance[i] * (heights[i - 1] - (heights[i - 1] if graph[i][i % 2 - 1] >= i else heights[i % 2 - 1]))
    return total_tiredness

if __name__ == "__main__":
    file = "input.txt"
    n, heights, tiredness, graph = read_input(file)
    shortest_distances = dijkstra(graph, 1)
    start = 1 if min(shortest_distances.values()) <= 500000 else 2
    result = solve(graph, heights, tiredness, start)
    print(result)
