class Edge:
    def __init__(self, u, v, w):
        self.u = u
        self.v = v
        self.w = w

def build_graph(n: int) -> List[Edge]:
    edges = []
    for _ in range(n - 1):
        u, v, w = read_ints()
        edges.append(Edge(u, v, w))
        edges.append(Edge(v, u, w))
    edges.append(Edge(n, 1, 0)) # dummy edge for keeping track of starting vertex
    return edges

def main():
    n, q = read_ints()
    values = read_ints()
    edges = build_graph(n)
    queries = [read_ints() for _ in range(q)]

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    profit = [0] * n
    first_time = defaultdict(int)
    for u in range(1, n + 1):
        for v, w in graph[u]:
            profit[v] = max(profit[v], w + profit[u])
        first_time[u] = 1

    memo = [[float('-inf')] * 2 for _ in range(q)]
    for u, v in queries:
        for prev, prof in memo:
            if first_time[u]:
                prev, prof = u, values[u] - sum(prof)
            if first_time[v]:
                prev, prof = v, values[v] - sum(prof)
            memo[(0, u)][1] = max(memo[(0, u)][1], prev, prev + w, prev + w + 2 * prof)
            memo[(1, u)][1] = max(memo[(1, u)][1], prev + w, prev + w + 2 * prof)
            memo[(2, u)][1] = max(memo[(2, u)][1], prev + 2 * prof)
            memo[(3, u)][1] = max(memo[(3, u)][1], prev + w + 2 * prof)

    for u, v in queries:
        qv, prev = memo[(0, u)][0], float('-inf')
        qv += values[u] - sum(prof)
        for ptr, (u, prof) in memo.items():
            if prv := prev:
                if ptr != 1: prv = memo[(1 - ptr, prv)][0]
                qv -= prv
            prev = sum(prof) + 2 * u
        print(qv)

