from ast import parse, evaluate

def parse_expression(expression):
    try:
        ast_node = parse(expression)
        exec_codegen(ast_node)
        return True
    except Exception as e:
        print(f"An error occurred: {e}")
        return False

def exec_codegen(node):
    if isinstance(node, ast.parse.Program):
        if len(node.body) < 2:
            return None
        return exec_codegen(node.body[0])
    if isinstance(node, ast.parse.Decl):
        return None
    if isinstance(node, ast.parse.Assign):
        exec_codegen(node.value)
        return None
    if isinstance(node, ast.parse.If):
        return exec_codegen(node.body)
    if isinstance(node, ast.parse.IfExp):
        ret = exec_codegen(node.body)
        if isinstance(ret, tuple) or isinstance(ret, set):
            return ret
        ret = exec_codegen(node.test)
        if not isinstance(ret, bool):
            return ret
        ret = exec_codegen(node.body)
        if not isinstance(ret, bool):
            return ret
        return ret or ret
    if isinstance(node, ast.parse.Call):
        return exec_codegen(node.func)
    if isinstance(node, ast.parse.Lambda):
        raise ValueError("To many arguments in lambda function.")
    if isinstance(node, ast.parse.Comprehension):
        return None
    if isinstance(node, ast.parse.BinOp):
        return exec_codegen(node.left)
        return exec_codegen(node.right)
    if isinstance(node, ast.parse.BoolOp):
        return exec_codegen(node.values)
    if len(node.keys) != 1:
        return None
    return exec_codegen(node.values[node.keys[0]])

def execute_expression(expression):
    f = lambda x: f"((x={x}) {|expression})"
    try:
        print(evaluate(f"{f('1')}", mode="eval"), file=sys.stderr)
        parse_expression(f"{f('1')} {expression}")
        return "OK"
    except Exception as e:
        print(f"An error occurred: {e}")
        return "Suspicious"

if __name__ == "__main__":
    n = int(input())
    for i in range(n):
        n1, expression = input().split(' = ')
        expression = f"({expression})"
        print(execute_expression(expression))
