from itertools import accumulate

def solve():
    n, m, q = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    k = int(input())

    # Build adjacency matrix
    adj = [[0]*m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            adj[i][j] = a[i] + b[j]

    def dijkstra(node):
        dist = [float('inf')]*n
        dist[node] = 0
        pq = [(0, node)]
        seen = {node}
        while pq:
            d, node = heappop(pq)
            if d > dist[node]:
                continue
            for next_node in range(n):
                if adj[next_node][node] > k:
                    if dist[next_node] > d + adj[next_node][node]:
                        dist[next_node] = d + adj[next_node][node]
                        heappush(pq, (dist[next_node], next_node))
        return dist

    q_max, q_min = float('-inf'), float('inf')
    max_dist, min_dist = dijkstra(0), dijkstra(n-1)
    for _ in range(q):
        x = int(input())
        if x <= k:
            q_max = max(q_max, max_dist[x])
            q_min = min(q_min, min_dist[x])
        else:
            q_max = max(q_max, max_dist[x])
            q_min = min(q_min, min_dist[x])

    if q_min < q_max:
        return q_max - q_min
    else:
        return q_min
