        s = list(s)
        s[i], s[-i-1] = s[-i-1], s[i]
        return int(''.join(s))

    n, m = len(S), len(T)
    queue = [(0, 0)]
    visited = [False] * (1 << m)
    visited[0] = True

    while queue:
        cost, j = queue.pop(0)
        if cost >= 2**m:
            return cost

        if j == n:
            return cost

        if visited[(1 << (m - 1)) ^ (1 << j)]:
            continue

        visited[(1 << (m - 1)) ^ (1 << j)] = True
        queue.append((cost + 1, j + 1))
        queue.append((cost + 1, j - 1))

        if j + 1 < n and S[j] == '0':
            queue.append((flip(S, j), j + 1))
