                else:
                    S[i] = 1
        if count_0 <= count_1:
            if count_0 == len(T) and len(S) == len(T):
                return 0
            return count_0 - count_1
        else:
            if count_1 == len(T) and len(S) == len(T):
                return 0
            return count_1 - count_0

    list_S = list(S)
    list_T = list(T)
    n = len(list_S)
    count = 0
    while set(list_S) ^ set(list_T):
        if ''.join(list_S) == ''.join(list_T):
