from collections import Counter

def alice_score(n, scores):
    c_freq = Counter(scores)

    def max_score(nums, pattern):
        dp = [-1] * len(nums)
        h = [0] * (len(nums) * 2)

        if any(nums[i] % 2 != n % 2 for i in range(len(nums))):
            return 0

        for i in range(len(nums)):
            h[i] = i

            for j in range(i + 2, len(nums), 2):
                if h[j - 1] > n + i % 2 - 1 and nums[j] % 2 != nums[j - 1] % 2:
                    h[j] = n + i % 2
                # minimum odd if nums[j] is odd, otherwise minimum even
                elif nums[j] % 2 % 2 == 0:
                    h[j] = h[j - 1]
                else:
                    h[j] = j
                    c = 1
                    t = pattern[h[j] - 1]
                    if t % 2 == 1:
                        c += h[j] - h[j - 1]
                    elif nums[h[j] - 1] % 2 == t % 2:
                        c += h[j] - h[j - 1] + 1
                    else:
                        c += h[j] - h[j - 1] + 2
                    dp[h[j]] = c
                # minimum odd if nums[j] is odd, otherwise minimum even
                h[j] = min(h[j - 1] + 2, pattern[h[j] - 1] - 2)

        return max(0, dp[-1])

    ans = []

    add = 0
    # number of odd numbers
    ans.append(add + sum([max_score(nums, 0) for nums in c_freq.values()]))
    # number of even numbers
    add = 0
    ans.append(add + sum([max_score(nums, 1) for nums in c_freq.values()]))

