import re

def calculate(expression):
    def evaluate(expression):
        if ' ' not in expression and '+' not in expression and '-' not in expression and '*' not in expression and '/' not in expression:
            return int(expression)
        tokens = re.findall(r'\d+|\D+', expression)
        operators = ['+', '-', '*', '/']
        stack = []
        temp = ''
        for char in tokens:
            if char.isdigit() or temp.isdigit():
                temp += char
            elif char in operators:
                while stack and stack[-1] in operators and precedence(stack[-1]) >= precedence(char):
                    evaluate_exp = stack.pop()
                    left = evaluate(str(stack.pop())[::-1]) if stack[-1] == '(' else int(stack.pop())
                    right = evaluate(str(stack.pop())[::-1]) if stack[-1] in ('+', '-') else int(stack.pop())
                    stack.append(evaluate_left(evaluate_right(left, right), evaluate_exp))
                temp += char
            else:
                stack.append(temp)
                temp = ''
        while stack:
            evaluate_exp = stack.pop()
            left = evaluate(str(stack.pop())[::-1]) if stack[-1] in ('+', '-') else int(stack.pop())
            right = evaluate(str(stack.pop())[::-1]) if stack[-1] == '(' else int(stack.pop())
            stack.append(evaluate_left(evaluate_right(left, right), evaluate_exp))
        return int(stack[0])
    def evaluate_left(a, b):
        if a / b == int(a) / int(b): 
            return int(a) / int(b)
        l, r = a * b, a / b
        p_left = precedence(l)
        p_right = precedence(r)
        if p_left > p_right:
            return r
        if p_left < p_right:
            return l
        if l < r:
            return r
        return l
    def precedence(op): 
        if op in ('+', '-'): 
            return 1
        if op in ('*', '/'): 
            return 2
        return -1
    return calculate(expression)

def main():
    num_macros = int(input())

    macros = []
    for _ in range(num_macros):
        name, value = input().split()
        macros.append((name, calculate(value)))

    expression = input()

    for macro_name, value in macros:
        print(f"Merging {type(value).__name__}('{value}') with {type(expression).__name__}({expression!r})...")
        value_str = str(value)
        result = calculate(f"{expression}{value_str}{expression}").replace('$', f'${value}').replace('$$', f'{value}$')
        if macro_name in result:
            print('Suspicious')
            return
    print('OK')

if __name__ == "__main__":
