        for u, v, w in tree:
            adjList[u].add((v, w))
            adjList[v].add((u, w))
        return adjList

    adjList = createAdjList()

    def findMaxProfit(queries):
        maxProfit = 0
        answer = defaultdict(int)
        for qu, qv in queries:
            profit = 0
            visited = set()
            stack = [(qu, 0)]
            while stack:
                u, factor = stack.pop()
                if u in visited:
                    continue
                visited.add(u)
                if u == qv:
                    moreFactor = 1
                else:
                    moreFactor = 2
                if u not in answer:
                    answer[u] = 0
                f, profit = answer[u]
                if f == 1:
                    rootProfit = 0
                    for to, weight in adjList[u]:
                        moreFactor *= weight
                        if to == qu:
                            continue
                        if to not in answer:
                            answer[to] = SystemExit
                        rootProfit += answer[to]
                    answer[u] = (moreFactor, profit - rootProfit)
                    maxProfit = max(maxProfit, profit)
                if moreFactor <= factor:
                    for to, weight in adjList[u]:
                        if moreFactor <= factor and to > u:
                            stack.append((to, weight))
                    if to != qv:
                        stack.append((u, factor))
                elif moreFactor > factor:
