                        moreFactor += weight
                        if moreFactor <= factor and to > u:
                            stack.append((to, weight))
                        elif to != qv and to > u:
                            stack.append((to, weight))
                        if to != qv and to > u:
                            stack.append((u, factor))
                    answer[u] = (moreFactor, profit)
                    maxProfit = max(maxProfit, profit)

