from typing import List

def min_palindrome_moves(N: int, A: List[int]) -> int:
    dp = [0] * (N + 1)
    count = 0
    for i in range(N, -1, -1):
        if i == N:
            dp[i] = 1
        else:
            for j in range(N, i):
                if A[i] == A[N-j]:
                    dp[i] = max(dp[i], dp[j+1] + 1)
            dp[i] += j + 1 - count
            count = count + 1 if A[i] == A[N-i] else 0
    return dp[0] - N

